import{_ as i,a0 as p,w as o,s as r,I as e,x as a,a1 as l,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何暂时禁用 iptables 防火墙 | LCTT x X-CMD","titleTemplate":false,"description":"如何暂时禁用 iptables 防火墙 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何暂时禁用 iptables 防火墙 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何暂时禁用 iptables 防火墙 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180619 How to disable iptables firewall temporarily","title":"如何暂时禁用 iptables 防火墙","tag":"201806","desc":""},"relativePath":"201806/20180619 How to disable iptables firewall temporarily.md","filePath":"[post].md"}'),b={name:"201806/20180619 How to disable iptables firewall temporarily.md"};function k(u,s,h,g,f,c){const n=p("Link");return o(),r("div",null,[s[20]||(s[20]=e("h1",{id:"如何暂时禁用-iptables-防火墙",tabindex:"-1"},[a("如何暂时禁用 iptables 防火墙 "),e("a",{class:"header-anchor",href:"#如何暂时禁用-iptables-防火墙","aria-label":"Permalink to “如何暂时禁用 iptables 防火墙”"},"​")],-1)),s[21]||(s[21]=e("blockquote",null,[e("p",null,"了解如何在 Linux 中暂时禁用 iptables 防火墙来进行故障排除。还要学习如何保存策略以及如何在启用防火墙时恢复它们。")],-1)),s[22]||(s[22]=e("p",null,[e("img",{src:"https://a2.kerneltalks.com/wp-content/uploads/2018/06/How-to-disable-iptables-firewall-temporarily.png",alt:"How to disable iptables firewall temporarily"})],-1)),e("p",null,[s[2]||(s[2]=a("有时你需要关闭 iptables 防火墙来做一些连接故障排除，然后你需要重新打开它。在执行此操作时，你还需要保存所有",-1)),l(n,{href:"https://kerneltalks.com/networking/configuration-of-iptables-policies/"},{default:t(()=>[...s[0]||(s[0]=[a("防火墙策略",-1)])]),_:1}),s[3]||(s[3]=a("。在本文中，我们将引导你了解如何保存防火墙策略以及如何禁用/启用 iptables 防火墙。有关 iptables 防火墙和策略的更多详细信息",-1)),l(n,{href:"https://kerneltalks.com/networking/basics-of-iptables-linux-firewall/"},{default:t(()=>[...s[1]||(s[1]=[a("请阅读我们的文章",-1)])]),_:1}),s[4]||(s[4]=a("。",-1))]),s[23]||(s[23]=d(`<h3 id="保存-iptables-策略" tabindex="-1">保存 iptables 策略 <a class="header-anchor" href="#保存-iptables-策略" aria-label="Permalink to “保存 iptables 策略”">​</a></h3><p>临时禁用 iptables 防火墙的第一步是保存现有的防火墙规则/策略。<code>iptables-save</code> 命令列出你可以保存到服务器中的所有现有策略。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # # iptables-save</span></span>
<span class="line"><span># Generated by iptables-save v1.4.21 on Tue Jun 19 09:54:36 2018</span></span>
<span class="line"><span>*nat</span></span>
<span class="line"><span>:PREROUTING ACCEPT [1:52]</span></span>
<span class="line"><span>:INPUT ACCEPT [1:52]</span></span>
<span class="line"><span>:OUTPUT ACCEPT [15:1140]</span></span>
<span class="line"><span>:POSTROUTING ACCEPT [15:1140]</span></span>
<span class="line"><span>:DOCKER - [0:0]</span></span>
<span class="line"><span>---- output trucated----</span></span>
<span class="line"><span></span></span>
<span class="line"><span>root@kerneltalks # iptables-save &gt; /root/firewall_rules.backup</span></span></code></pre></div><p>因此，iptables-save 是可以用来备份 iptables 策略的命令。</p><h3 id="停止-禁用-iptables-防火墙" tabindex="-1">停止/禁用 iptables 防火墙 <a class="header-anchor" href="#停止-禁用-iptables-防火墙" aria-label="Permalink to “停止/禁用 iptables 防火墙”">​</a></h3><p>对于较老的 Linux 内核，你可以选择使用 <code>service iptables stop</code> 停止 iptables 服务，但是如果你在用新内核，则只需清除所有策略并允许所有流量通过防火墙。这和你停止防火墙效果一样。</p><p>使用下面的命令列表来做到这一点。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # iptables -F</span></span>
<span class="line"><span>root@kerneltalks # iptables -X</span></span>
<span class="line"><span>root@kerneltalks # iptables -P INPUT ACCEPT</span></span>
<span class="line"><span>root@kerneltalks # iptables -P OUTPUT ACCEPT</span></span>
<span class="line"><span>root@kerneltalks # iptables -P FORWARD ACCEPT</span></span></code></pre></div><p>这里 –</p><ul><li><code>-F</code>：删除所有策略链</li><li><code>-X</code>：删除用户定义的链</li><li><code>-P INPUT/OUTPUT/FORWARD</code> ：接受指定的流量</li></ul><p>完成后，检查当前的防火墙策略。它应该看起来像下面这样接受所有流量（和禁用/停止防火墙一样）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># iptables -L</span></span>
<span class="line"><span>Chain INPUT (policy ACCEPT)</span></span>
<span class="line"><span>target     prot opt source               destination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chain FORWARD (policy ACCEPT)</span></span>
<span class="line"><span>target     prot opt source               destination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chain OUTPUT (policy ACCEPT)</span></span>
<span class="line"><span>target     prot opt source               destination</span></span></code></pre></div><h3 id="恢复防火墙策略" tabindex="-1">恢复防火墙策略 <a class="header-anchor" href="#恢复防火墙策略" aria-label="Permalink to “恢复防火墙策略”">​</a></h3><p>故障排除后，你想要重新打开 iptables 的所有配置。你需要先从我们在第一步中执行的备份中恢复策略。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # iptables-restore &lt;/root/firewall_rules.backup</span></span></code></pre></div><h3 id="启动-iptables-防火墙" tabindex="-1">启动 iptables 防火墙 <a class="header-anchor" href="#启动-iptables-防火墙" aria-label="Permalink to “启动 iptables 防火墙”">​</a></h3><p>然后启动 iptables 服务，以防止你在上一步中使用 <code>service iptables start</code> 停止了它。如果你已经停止服务，那么只有恢复策略才能有用。检查所有策略是否恢复到 iptables 配置中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#  iptables -L</span></span>
<span class="line"><span>Chain INPUT (policy ACCEPT)</span></span>
<span class="line"><span>target     prot opt source               destination</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>Chain FORWARD (policy DROP)</span></span>
<span class="line"><span>target     prot opt source               destination</span></span>
<span class="line"><span>DOCKER-USER  all  --  anywhere             anywhere</span></span>
<span class="line"><span>DOCKER-ISOLATION-STAGE-1  all  --  anywhere             anywhere</span></span>
<span class="line"><span>-----output truncated-----</span></span></code></pre></div><p>就是这些了！你已成功禁用并启用了防火墙，而不会丢失你的策略规则。</p><hr>`,20)),e("p",null,[s[6]||(s[6]=a("via: ",-1)),l(n,{href:"https://kerneltalks.com/howto/how-to-disable-iptables-firewall-temporarily/"},{default:t(()=>[...s[5]||(s[5]=[a("https://kerneltalks.com/howto/how-to-disable-iptables-firewall-temporarily/",-1)])]),_:1})]),e("p",null,[s[11]||(s[11]=a("作者：",-1)),l(n,{href:"https://kerneltalks.com"},{default:t(()=>[...s[7]||(s[7]=[a("kerneltalks",-1)])]),_:1}),s[12]||(s[12]=a(" 选题：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),l(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=a("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),l(n,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const P=i(b,[["render",k]]);export{m as __pageData,P as default};
